-- Arquivo: schema_sql_aplicados.sql
-- ═══════════════════════════════════════════════════════════════════════
-- Registro dos SQL rodados (08/10/2026)
-- ═══════════════════════════════════════════════════════════════════════
-- 1. Tabela sql_aplicados: cada SQL novo termina com
--      select public.sql_registrar('nome_do_arquivo.sql');
--    e fica anotado o dia em que rodou.
-- 2. Conferência dos 142 arquivos antigos da pasta crm: pra cada um, olha no
--    banco se o que ele cria existe (tabelas, colunas, funções na versão
--    do arquivo, índices, políticas, gatilhos, buckets) e anota:
--      rodado        tudo o que ele cria está no banco
--      parcial       só uma parte (ou algo foi trocado depois por outro SQL)
--      nao_rodado    nada do que ele cria está no banco
--      sem_marcador  só mexe em dados ou permissões, não dá pra conferir
-- 3. Função sql_situacao(): o Claude consulta a situação dos arquivos pelo
--    nome (só devolve os nomes pedidos, não lista nada).
--
-- Rodar no Supabase: SQL Editor do projeto go-ladies-crm. Seguro rodar de
-- novo (refaz a conferência; não apaga o que foi registrado).
-- ═══════════════════════════════════════════════════════════════════════

create table if not exists public.sql_aplicados (
  arquivo text primary key,
  situacao text not null,              -- rodado | parcial | nao_rodado | sem_marcador
  origem text not null,                -- registro (o SQL se anotou) | conferido (pela conferência)
  rodado_em timestamptz,               -- só quando o próprio SQL se registrou
  vezes int not null default 0,        -- quantas vezes se registrou
  conferido_em timestamptz,
  detalhe text                         -- o que falta no banco, na conferência
);

alter table public.sql_aplicados enable row level security;
drop policy if exists "Equipe vê sql_aplicados" on public.sql_aplicados;
create policy "Equipe vê sql_aplicados" on public.sql_aplicados
  for select using (public.eh_staff());

-- ── Registrar (vai no fim de cada SQL novo) ────────────────────────────
create or replace function public.sql_registrar(p_arquivo text)
returns void
language sql
security definer
set search_path = public
as $$
  insert into public.sql_aplicados (arquivo, situacao, origem, rodado_em, vezes)
  values (p_arquivo, 'rodado', 'registro', now(), 1)
  on conflict (arquivo) do update
    set situacao = 'rodado', origem = 'registro', rodado_em = now(),
        vezes = public.sql_aplicados.vezes + 1, detalhe = null;
$$;
revoke execute on function public.sql_registrar(text) from public, anon, authenticated;

-- ── Consultar (o Claude usa pra saber se um SQL já rodou) ───────────────
create or replace function public.sql_situacao(p_arquivos text[])
returns table (arquivo text, situacao text, origem text, rodado_em timestamptz, detalhe text)
language sql
security definer
set search_path = public
stable
as $$
  select s.arquivo, s.situacao, s.origem, s.rodado_em, s.detalhe
  from public.sql_aplicados s
  where s.arquivo = any(p_arquivos[1:400]);
$$;
revoke execute on function public.sql_situacao(text[]) from public;
grant execute on function public.sql_situacao(text[]) to anon, authenticated;

