r as (
  select m.arquivo, m.tipo, m.a, m.b,
    case m.tipo
      when 'tabela'    then to_regclass('public.' || m.a) is not null
      when 'coluna'    then exists (select 1 from information_schema.columns c
                                    where c.table_schema = 'public' and c.table_name = m.a and c.column_name = m.b)
      when 'restricao' then exists (select 1 from pg_constraint c where c.conname = m.a)
      when 'indice'    then exists (select 1 from pg_indexes i where i.indexname = m.a)
      when 'politica'  then exists (select 1 from pg_policies p where p.policyname = m.a and p.tablename = m.b)
      when 'gatilho'   then exists (select 1 from pg_trigger t where t.tgname = m.a and not t.tgisinternal)
      when 'apagado_depois' then true
      when 'politica_se_tabela' then to_regclass('public.' || m.b) is null
                                    or exists (select 1 from pg_policies p where p.policyname = m.a and p.tablename = m.b)
      when 'gatilho_removido' then not exists (select 1 from pg_trigger t where t.tgname = m.a and not t.tgisinternal)
      when 'bucket'    then exists (select 1 from storage.buckets k where k.id = m.a)
      when 'funcao'    then exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                                    where n.nspname = 'public' and p.proname = m.a
                                      and md5(regexp_replace(p.prosrc, '\s', '', 'g')) = any(m.hashes))
    end as ok
  from m
),
porarq as (
  select arquivo,
    count(tipo) as total,
    count(*) filter (where ok) as oks,
    string_agg(case when tipo is not null and not ok then
      tipo || ' ' || a || coalesce('.' || b, '') ||
      case when tipo = 'funcao' then ' (versão diferente ou não existe)'
           when tipo = 'gatilho_removido' then ' (ainda existe)' else '' end
    end, '; ') as falta
  from r group by arquivo
)
insert into public.sql_aplicados as s (arquivo, situacao, origem, conferido_em, detalhe)
select arquivo,
  case when total = 0 then 'sem_marcador'
       when oks = total then 'rodado'
       when oks = 0 then 'nao_rodado'
       else 'parcial' end,
  'conferido', now(), left(falta, 1000)
from porarq
on conflict (arquivo) do update
  set situacao = case when s.origem = 'registro' then s.situacao else excluded.situacao end,
      conferido_em = excluded.conferido_em,
      detalhe = case when s.origem = 'registro' then s.detalhe else excluded.detalhe end;

select public.sql_registrar('schema_sql_aplicados.sql');

-- Resumo pra conferir na hora (aparece embaixo, em Results):
select situacao, count(*) as arquivos
from public.sql_aplicados group by situacao order by 1;
